; ---------------------------------------------------------------
; void __near__ draw_enemy (struct $anon-struct-0002 *enemy)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_draw_enemy: near

.segment	"CODE"

;
; {
;
	jsr     pushax
;
; if (enemy->used == 1)
;
	ldy     #$01
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	lda     (ptr1),y
	cmp     #$01
	jne     L000F
;
; if ((enemy->type & 0b01111111) == 0 || ((enemy->type & 0b01111111) == 1 && (enemy->self_timer > 100)))
;
	iny
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$06
	lda     (ptr1),y
	and     #$7F
	beq     L001B
	ldy     #$01
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$06
	lda     (ptr1),y
	and     #$7F
	cmp     #$01
	bne     L000C
	tay
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$05
	lda     (ptr1),y
	cmp     #$65
	bcc     L000C
;
; if (enemy->type & 0b10000000)
;
L001B:	ldy     #$01
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$06
	lda     (ptr1),y
	and     #$80
	beq     L000B
;
; oam_meta_spr(enemy->x, enemy->y, ship_enemy0_Metasprite_DOWN_data);
;
	jsr     decsp2
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	dey
	lda     (ptr1),y
	sta     (c_sp),y
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	iny
	lda     (ptr1),y
	ldy     #$00
	sta     (c_sp),y
	lda     #<(_ship_enemy0_Metasprite_DOWN_data)
	ldx     #>(_ship_enemy0_Metasprite_DOWN_data)
;
; else
;
	jmp     L0015
;
; oam_meta_spr(enemy->x, enemy->y, ship_enemy0_Metasprite_UP_data);
;
L000B:	jsr     decsp2
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	dey
	lda     (ptr1),y
	sta     (c_sp),y
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	iny
	lda     (ptr1),y
	ldy     #$00
	sta     (c_sp),y
	lda     #<(_ship_enemy0_Metasprite_UP_data)
	ldx     #>(_ship_enemy0_Metasprite_UP_data)
L0015:	jsr     _oam_meta_spr
;
; if ((enemy->type & 0b01111111) == 1)
;
L000C:	ldy     #$01
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$06
	lda     (ptr1),y
	and     #$7F
	cmp     #$01
	bne     L000F
;
; if ((enemy->self_timer < 60) && (enemy->self_timer & 1))
;
	tay
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$05
	lda     (ptr1),y
	cmp     #$3C
	bcs     L000F
	ldy     #$01
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	ldy     #$05
	lda     (ptr1),y
	and     #$01
	beq     L000F
;
; oam_meta_spr(enemy->x, enemy->y, ship_enemy_warn_Metasprite);
;
	jsr     decsp2
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	dey
	lda     (ptr1),y
	sta     (c_sp),y
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	iny
	lda     (ptr1),y
	ldy     #$00
	sta     (c_sp),y
	lda     #<(_ship_enemy_warn_Metasprite)
	ldx     #>(_ship_enemy_warn_Metasprite)
	jsr     _oam_meta_spr
;
; if (enemy->used == 2)
;
L000F:	ldy     #$01
	lda     (c_sp),y
	sta     ptr1+1
	dey
	lda     (c_sp),y
	sta     ptr1
	lda     (ptr1),y
	cmp     #$02
	bne     L0013
;
; oam_meta_spr(enemy->x, enemy->y, explosion_list[enemy->self_timer & 0b1]);
;
	jsr     decsp2
	ldy     #$03
	lda     (c_sp),y
	sta     ptr1+1
